-- TORVO V2 secure business RPCs. Staging runtime verification required.
create or replace function approve_dealer(p_dealer uuid,p_dealer_code text,p_rate_group text) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;s text;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin') then raise exception 'Not authorized';end if;if p_rate_group not in('A','B','C') or nullif(trim(p_dealer_code),'') is null then raise exception 'Dealer code and valid rate group required';end if;select status into s from dealers where id=p_dealer for update;if not found then raise exception 'Dealer not found';end if;update dealers set dealer_code=upper(trim(p_dealer_code)),rate_group=p_rate_group,status='approved',approved_by=a.id,approved_at=now() where id=p_dealer;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'DEALER_APPROVED','dealer',p_dealer::text,jsonb_build_object('dealer_code',upper(trim(p_dealer_code)),'rate_group',p_rate_group));end;$$;
create or replace function set_dealer_request_status(p_dealer uuid,p_status text,p_reason text) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;old_status text;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin') then raise exception 'Not authorized';end if;if p_status not in('pending','hold','rejected','inactive','suspended') or nullif(trim(p_reason),'') is null then raise exception 'Valid status and reason required';end if;select status into old_status from dealers where id=p_dealer for update;if not found then raise exception 'Dealer not found';end if;update dealers set status=p_status where id=p_dealer;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'DEALER_STATUS_CHANGED','dealer',p_dealer::text,jsonb_build_object('old_status',old_status,'new_status',p_status,'reason',trim(p_reason)));end;$$;
create or replace function set_dealer_rate_group(p_dealer uuid,p_rate_group text,p_reason text) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;old_group text;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin') then raise exception 'Not authorized';end if;if p_rate_group not in('A','B','C') or nullif(trim(p_reason),'') is null then raise exception 'Valid rate group and reason required';end if;select rate_group into old_group from dealers where id=p_dealer and status='approved' for update;if not found then raise exception 'Approved dealer required';end if;update dealers set rate_group=p_rate_group where id=p_dealer;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'DEALER_RATE_GROUP_CHANGED','dealer',p_dealer::text,jsonb_build_object('old_rate_group',old_group,'new_rate_group',p_rate_group,'reason',trim(p_reason)));end;$$;
create or replace function set_delivery_settings(p_enabled boolean,p_threshold numeric,p_reason text) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;s delivery_settings%rowtype;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin') then raise exception 'Not authorized';end if;if p_threshold<0 or nullif(trim(p_reason),'') is null then raise exception 'Threshold and reason required';end if;select * into s from delivery_settings where id=true for update;insert into delivery_setting_history(old_enabled,old_threshold,new_enabled,new_threshold,reason,changed_by) values(s.spare_free_delivery_enabled,s.spare_free_delivery_threshold,p_enabled,p_threshold,trim(p_reason),a.id);update delivery_settings set spare_free_delivery_enabled=p_enabled,spare_free_delivery_threshold=p_threshold,updated_by=a.id,updated_at=now() where id=true;end;$$;
create or replace function set_gst_billing_mode(p_enabled boolean,p_pricing_mode text,p_reason text) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;s tax_settings%rowtype;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin') then raise exception 'Not authorized';end if;if p_pricing_mode not in('included','extra') or nullif(trim(p_reason),'') is null then raise exception 'Pricing mode and reason required';end if;select * into s from tax_settings where id=true for update;update tax_settings set gst_billing_enabled=p_enabled,default_pricing_mode=p_pricing_mode,updated_by=a.id,updated_at=now() where id=true;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'GST_BILLING_MODE_CHANGED','tax_settings','GLOBAL',jsonb_build_object('old_enabled',s.gst_billing_enabled,'new_enabled',p_enabled,'old_pricing_mode',s.default_pricing_mode,'new_pricing_mode',p_pricing_mode,'reason',trim(p_reason)));end;$$;
-- Counter row is transaction-locked. If the transaction rolls back, the counter update rolls back too, unlike nextval().
create or replace function issue_final_sale_serial(p_estimate uuid) returns bigint language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;d sales_documents%rowtype;n bigint;paid numeric;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin','accountant') then raise exception 'Not authorized';end if;select * into d from sales_documents where id=p_estimate and doc_type='estimate' for update;if not found then raise exception 'Estimate not found';end if;if d.final_sale_serial is not null then return d.final_sale_serial;end if;select coalesce(sum(amount),0) into paid from payments where estimate_id=p_estimate and status in('cash','received');if paid<d.final_payable then raise exception 'Full payment not received';end if;select last_serial into n from final_sale_serial_counter where id=true for update;n:=n+1;update final_sale_serial_counter set last_serial=n,updated_at=now() where id=true;update sales_documents set final_sale_serial=n,final_sale_serial_issued_at=now() where id=p_estimate;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'FINAL_SALE_SERIAL_ISSUED','estimate',p_estimate::text,jsonb_build_object('serial',n));return n;end;$$;
create or replace function record_payment(p_estimate uuid,p_status text,p_amount numeric,p_request_key text) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;pid uuid;f numeric;already numeric;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin','accountant') then raise exception 'Not authorized';end if;if p_status not in('cash','pending','received') or p_amount<=0 or nullif(trim(p_request_key),'') is null then raise exception 'Valid payment required';end if;select final_payable into f from sales_documents where id=p_estimate and doc_type='estimate' for update;if not found then raise exception 'Estimate not found';end if;select coalesce(sum(amount),0) into already from payments where estimate_id=p_estimate and status in('cash','received');if p_status in('cash','received') and already+p_amount>f then raise exception 'Payment exceeds estimate payable';end if;insert into payments(estimate_id,status,amount,received_at,recorded_by) values(p_estimate,p_status,p_amount,case when p_status in('cash','received') then now() end,a.id) returning id into pid;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'INTERNAL_PAYMENT_NOTED','estimate',p_estimate::text,jsonb_build_object('payment_id',pid,'status',p_status,'amount',p_amount,'request_key',trim(p_request_key)));return pid;end;$$;
create or replace function create_accounting_balance(p_estimate uuid,p_amount numeric,p_remarks text default null) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;bid uuid;did uuid;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin','accountant') then raise exception 'Not authorized';end if;if p_amount<=0 then raise exception 'Balance amount must be greater than zero';end if;select dealer_id into did from sales_documents where id=p_estimate and doc_type='estimate';if not found then raise exception 'Estimate not found';end if;insert into accounting_balances(estimate_id,dealer_id,balance_amount,remarks) values(p_estimate,did,p_amount,nullif(trim(p_remarks),'')) returning id into bid;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'ACCOUNTING_BALANCE_CREATED','accounting_balance',bid::text,jsonb_build_object('estimate_id',p_estimate,'amount',p_amount));return bid;end;$$;
create or replace function mark_accounting_balance_entered(p_balance uuid,p_entry_no text) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;b accounting_balances%rowtype;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin','accountant') then raise exception 'Not authorized';end if;if nullif(trim(p_entry_no),'') is null then raise exception 'Accounting entry number required';end if;select * into b from accounting_balances where id=p_balance for update;if not found or b.status<>'pending' then raise exception 'Pending balance required';end if;update accounting_balances set status='accounting_entered',accounting_entry_no=upper(trim(p_entry_no)),accounting_entered_at=now(),accounting_entered_by=a.id where id=p_balance;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'ACCOUNTING_BALANCE_ENTERED','accounting_balance',p_balance::text,jsonb_build_object('accounting_entry_no',upper(trim(p_entry_no))));end;$$;
create or replace function advance_dispatch(p_estimate uuid,p_status text,p_tracking_code text default null) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;cur text;nxt text;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin','store_keeper') then raise exception 'Not authorized';end if;if p_status='delivered' then raise exception 'Use controlled delivery finalization';end if;select status into cur from dispatches where estimate_id=p_estimate for update;if not found then raise exception 'Dispatch not found';end if;nxt:=case cur when 'pick_list' then 'picked' when 'picked' then 'packed' when 'packed' then 'ready_for_dispatch' end;if p_status<>nxt then raise exception 'Invalid dispatch transition';end if;update dispatches set status=p_status,tracking_code=coalesce(nullif(trim(p_tracking_code),''),tracking_code),updated_by=a.id where estimate_id=p_estimate;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'DISPATCH_STATUS_CHANGED','estimate',p_estimate::text,jsonb_build_object('from',cur,'to',p_status));end;$$;
-- GST invoice requires explicit Owner/Admin approval and snapshots tax values.
create or replace function approve_gst_invoice(p_estimate uuid,p_reason text) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;ts tax_settings%rowtype;d sales_documents%rowtype;inv uuid;ln record;taxable numeric;gst numeric;taxable_sum numeric:=0;gst_sum numeric:=0;invoice_sum numeric:=0;serial_no bigint;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin') then raise exception 'Owner/Admin approval required';end if;if nullif(trim(p_reason),'') is null then raise exception 'Approval reason required';end if;select * into ts from tax_settings where id=true;if not found or not ts.gst_billing_enabled then raise exception 'GST billing is OFF';end if;select * into d from sales_documents where id=p_estimate and doc_type='estimate' for update;if not found then raise exception 'Estimate not found';end if;if exists(select 1 from gst_invoices where estimate_id=p_estimate) then raise exception 'GST invoice already exists';end if;serial_no:=issue_final_sale_serial(p_estimate);insert into gst_invoices(estimate_id,status,pricing_mode,torvo_final_serial,approved_by,approved_at) values(p_estimate,'approved',ts.default_pricing_mode,serial_no,a.id,now()) returning id into inv;for ln in select l.*,c.item_code,c.name,c.hsn_code,coalesce(c.gst_rate,0) gst_rate,coalesce(c.gst_mode,ts.default_pricing_mode) line_mode from sales_document_lines l join catalog_items c on c.id=l.item_id where l.document_id=p_estimate loop if ln.line_mode='included' and ln.gst_rate>0 then taxable:=round(coalesce(ln.amount,ln.qty*ln.rate)/(1+ln.gst_rate/100),2);gst:=round(coalesce(ln.amount,ln.qty*ln.rate)-taxable,2);else taxable:=round(coalesce(ln.amount,ln.qty*ln.rate),2);gst:=case when ln.line_mode='extra' then round(taxable*ln.gst_rate/100,2) else 0 end;end if;insert into gst_invoice_lines(invoice_id,item_id,item_code_snapshot,item_name_snapshot,hsn_snapshot,gst_rate_snapshot,qty,rate_snapshot,line_total,taxable_value,gst_amount) values(inv,ln.item_id,ln.item_code,ln.name,ln.hsn_code,ln.gst_rate,ln.qty,ln.rate,round(taxable+gst,2),taxable,gst);taxable_sum:=taxable_sum+taxable;gst_sum:=gst_sum+gst;invoice_sum:=invoice_sum+taxable+gst;end loop;update gst_invoices set taxable_total=round(taxable_sum,2),gst_total=round(gst_sum,2),invoice_total=round(invoice_sum+d.freight+d.other_charges,2) where id=inv;insert into gst_invoice_approval_history(invoice_id,action,reason,actor_id) values(inv,'APPROVED',trim(p_reason),a.id);insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'GST_INVOICE_APPROVED','gst_invoice',inv::text,jsonb_build_object('estimate_id',p_estimate,'torvo_final_serial',serial_no,'reason',trim(p_reason)));return inv;end;$$;
revoke all on function approve_dealer(uuid,text,text),set_dealer_request_status(uuid,text,text),set_dealer_rate_group(uuid,text,text),set_delivery_settings(boolean,numeric,text),set_gst_billing_mode(boolean,text,text),issue_final_sale_serial(uuid),record_payment(uuid,text,numeric,text),create_accounting_balance(uuid,numeric,text),mark_accounting_balance_entered(uuid,text),advance_dispatch(uuid,text,text),approve_gst_invoice(uuid,text) from public,anon;
grant execute on function approve_dealer(uuid,text,text),set_dealer_request_status(uuid,text,text),set_dealer_rate_group(uuid,text,text),set_delivery_settings(boolean,numeric,text),set_gst_billing_mode(boolean,text,text),issue_final_sale_serial(uuid),record_payment(uuid,text,numeric,text),create_accounting_balance(uuid,numeric,text),mark_accounting_balance_entered(uuid,text),advance_dispatch(uuid,text,text),approve_gst_invoice(uuid,text) to authenticated;
